}

export interface AuthorityLookup {
	readonly available: boolean;
	readonly authorityId?: string;
	readonly node?: Node<unknown>;
}

export interface SpendingInspection {
	/** Complete owning Graph snapshot: nodes AND edges, never counts or a filtered subgraph. */
	readonly graph: GraphSnapshot;
	/** Target instance host records and readiness, from the target's own inspect(). */
	readonly host: HostInspection;
	/** Current publication of the target, or undefined when it has not published yet. */
	readonly publication: Publication | undefined;
	/** Retained quiescence of the target, or undefined when not yet retained. */
	readonly retainedQuiescence: CausalQuiescence | undefined;
	/** Authority lookup derived from the target's CURRENT publication only. */
	readonly authority: AuthorityLookup;
}

/**
 * Read-only inspection. `graph` is the owning Graph; `app` is the actual composed
 * instance (e.g. the object returned by spendingAlertsFor(...).compose(...)).
 * The target is addressed by its own references, never by graph enumeration order
 * and never by a name-suffix search.
 */
export function inspectSpendingInstance(
	graph: Graph,
	app: ComposedSpendingInstance,
): SpendingInspection {
	// 1. Complete owning Graph snapshot (README.md:109, 117-118).
	const described = graph.describe();
	const graphSnapshot: GraphSnapshot = Object.freeze({
		name: described.name,
		nodes: Object.freeze(described.nodes.map((n) => Object.freeze({ id: n.id }))),
		edges: Object.freeze(described.edges.map((e) => Object.freeze({ from: e.from, to: e.to }))),
	});

	// 2. Target host records/readiness from the target's own inspect().
	const host = app.inspect();

	// 3. Current publication of the target (README.md:111).
	const publication = app.consume.view.publication.cache;

	// 4. Retained quiescence of the target (README.md:112).
	const retainedQuiescence = app.consume.capabilities.retained.retainedQuiescence.cache;

	// 5. Authority lookup tied to THIS target's current publication (README.md:113-122).
	//    No publication => unavailable, even if another instance has published.
	const authorityId = publication?.authorityId;
	const authority: AuthorityLookup =
		authorityId === undefined
			? Object.freeze({ available: false })
			: Object.freeze({
					available: true,
					authorityId,
					node: graph.find(authorityId),
				});

	return Object.freeze({
		graph: graphSnapshot,
		host,
		publication,
		retainedQuiescence,
		authority,
	});
}
